using UnityEngine;

public class GenericPool<T> where T : class
{
	public static Vector2 initSpawnVec = new Vector2(-200f, 0f);

	private T[] items;

	private int itemIndex;

	private int itemCount;

	public GameObject poolObj;

	public string name;

	public int ItemCount => itemCount;

	public GenericPool(string givenPath, int givenCount = 10, string givenName = "", bool dontDestroyOnLoad = true, Transform givenParent = null)
	{
		InitPool(ChaosBundle.Get(givenPath), givenCount, givenName, dontDestroyOnLoad, givenParent);
	}

	public GenericPool(GameObject givenPrefab, int givenCount = 10, Transform givenParent = null)
	{
		InitPool(givenPrefab, givenCount, string.Empty, givenDestroyOnLoad: false, givenParent);
	}

	private void InitPool(GameObject givenPrefab, int givenCount, string givenName = "", bool givenDestroyOnLoad = true, Transform givenParent = null)
	{
		itemCount = givenCount;
		items = new T[givenCount];
		itemIndex = 0;
		if (givenName == string.Empty)
		{
			givenName = givenPrefab.name + "Pool";
		}
		poolObj = new GameObject(givenName);
		if (givenDestroyOnLoad)
		{
			Object.DontDestroyOnLoad(poolObj);
		}
		poolObj.transform.SetParent(givenParent);
		for (int i = 0; i < itemCount; i++)
		{
			items[i] = Object.Instantiate(givenPrefab, initSpawnVec, givenPrefab.transform.rotation, poolObj.transform).GetComponentInChildren<T>();
		}
	}

	public T GetItem()
	{
		itemIndex++;
		if (itemIndex >= itemCount)
		{
			itemIndex = 0;
		}
		return items[itemIndex];
	}
}
