	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/EnemySkills/ChaosBarrier.prefab"));
	private void Awake()
	{
		anim = GetComponent<Animator>();
		if (pSysOverride == null)
		{
			ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
			particleSystemOverride.startColor = new Color(0.72941f, 0.56863f, 0.76471f, 0.75f);
			particleSystemOverride.startLifetime = 0.66f;
			particleSystemOverride.radius = 2f;
			pSysOverride = particleSystemOverride;
		}
		spriteRenderers = GetComponentsInChildren<SpriteRenderer>();
	}
	private void Start()
	{
		if (this.health == null)
		{
			BreakShield();
			return;
		}
		Health health = this.health;
		health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(DamageEventHandler));
		SoundManager.PlayAudioWithDistance("ChaosBarrier", transform.position);
	}
	private void Update()
	{
		if (!destroyQueued && (health == null || (float)health.CurrentShieldValue <= 0f))
		{
			BreakShield();
		}
	}
	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}
	private void BreakShield()
	{
		if (destroyQueued)
		{
			return;
		}
		if (this.health != null)
		{
			Health health = this.health;
			health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(DamageEventHandler));
		}
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffectLarge").Emit(40, transform.position + new Vector3(0f, 1.25f, 0f), pSysOverride);
		anim.Play("Break", -1, 0f);
		destroyQueued = true;
		if (finalBoss != null)
		{
			finalBoss.ToggleShieldHurtBox(enable: false);
			if (!finalBoss.fsm.currentStateName.Contains("Hurt"))
			{
				finalBoss.fsm.QueueChangeState(finalBoss.bossHurtState.name);
			}
		}
	}
	private void OnDestroy()
	{
		if (this.health != null)
		{
			Health health = this.health;
			health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(DamageEventHandler));
		}
	}
	private void DamageEventHandler(AttackInfo attackInfo, Entity attackEntity)
	{
		if (!destroyQueued)
		{
			StartCoroutine(Flash());
		}
	}
	public void Initialize(Transform givenTrans, Health givenHealth, FinalBoss finalBoss)
	{
		followTrans = givenTrans;
		health = givenHealth;
		this.finalBoss = finalBoss;
	}
	public IEnumerator Flash()
	{
		if (spriteRenderers.Length == 0)
		{
			yield break;
		}
		for (int i = 0; i < spriteRenderers.Length; i++)
		{
			if (!(spriteRenderers[i] == null))
			{
				spriteRenderers[i].material.SetFloat("_FlashAmount", 0.35f);
			}
		}
		yield return waitForFlashDelay;
		for (int j = 0; j < spriteRenderers.Length; j++)
		{
			if (!(spriteRenderers[j] == null))
			{
				spriteRenderers[j].material.SetFloat("_FlashAmount", 0f);
			}
		}
	}
}
